const items = $input.all();

return items.map(item => {
  let output = String(item.json.output ?? '');

  // Convert literal \n text into real line breaks
  output = output.replace(/\\n/g, '\n');

  // Remove escaped Markdown bold markers
  output = output.replace(/\\\*/g, '');
  output = output.replace(/https\\:/g, 'https:');
  output = output.replace(/\*\*/g, '');

  return {
    json: {
      ...item.json,
      output,
      containsLiteralBackslashN: output.includes('\\n'),
      containsRealNewline: output.includes('\n')
    }
  };
});
